#!/usr/bin/env python3
from __future__ import annotations

import argparse
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import subprocess
import sys
import time
from typing import Callable
import urllib.error
import urllib.request
from datetime import datetime, timezone

try:
    from tools.tef_a4_resolution import (
        A4_AUDITOR_EVIDENCE_FIELDS,
        A4_RESOLVER_VERSION,
        REFUTATION_VALIDITY_VERSION,
        RESOLVED,
        resolve_a4_evidence,
        validate_resolution_bundle,
    )
except ModuleNotFoundError:  # Direct execution: python tools/tef_audit_runner.py
    from tef_a4_resolution import (  # type: ignore[no-redef]
        A4_AUDITOR_EVIDENCE_FIELDS,
        A4_RESOLVER_VERSION,
        REFUTATION_VALIDITY_VERSION,
        RESOLVED,
        resolve_a4_evidence,
        validate_resolution_bundle,
    )

API_URL = "https://api.groq.com/openai/v1/chat/completions"
ALLOWED_PROVIDER = "groq"
ALLOWED_MODEL = "openai/gpt-oss-120b"

SYSTEM = (
    "You are a TEF audit stage executor. Use only the frozen request and concrete "
    "evidence package. Do not redesign the audited unit, invent evidence, normalize "
    "adverse findings, or execute A5. Return JSON only in the stage schema."
)

REQUIRED_FIELDS = {
    "request_id",
    "unit",
    "evaluated_baseline",
    "provider",
    "model",
    "zero_cost_only",
    "a3_input",
    "a4_input",
    "evidence_manifest",
    "result_directory",
    "a3_instance_id",
    "a4_instance_id",
    "a4_independence_required",
    "a4_independent_instance_id",
    "claims",
    "limits",
    "max_output_tokens_per_stage",
    "provider_tpm_limit",
    "token_safety_margin",
    "min_seconds_between_stages",
}

# Groq documents TPM as input plus requested output tokens.  The provider does
# not expose a local tokenizer for this model, so pre-flight uses the established
# UTF-8/4 estimate and reserves an explicit request-level safety margin.  The
# margin is request data, not a hidden runner constant, and absorbs tokenizer and
# chat-envelope variance.  A package is sent only when the complete declared
# budget is strictly within the provider TPM limit.
TOKEN_ESTIMATE_BYTES_PER_TOKEN = 4


class AuditRequestError(RuntimeError):
    pass


def sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def canonical_bytes(value: object) -> bytes:
    return json.dumps(
        value, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _read_json(path: Path, description: str) -> dict:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise AuditRequestError(f"invalid or missing {description}: {path}") from exc
    if type(value) is not dict:
        raise AuditRequestError(f"{description} must be a JSON object")
    return value


def load_request(request_path: Path) -> dict:
    request_path = request_path.resolve()
    request = _read_json(request_path, "request")
    missing = sorted(REQUIRED_FIELDS - request.keys())
    if missing:
        raise AuditRequestError(f"missing request fields: {', '.join(missing)}")
    if request["provider"] != ALLOWED_PROVIDER:
        raise AuditRequestError("provider must remain groq")
    if request["model"] != ALLOWED_MODEL:
        raise AuditRequestError(f"model must remain {ALLOWED_MODEL}")
    if request["zero_cost_only"] is not True:
        raise AuditRequestError("zero_cost_only must be true")
    for name in (
        "request_id",
        "unit",
        "evaluated_baseline",
        "a3_instance_id",
        "a4_instance_id",
        "a4_independent_instance_id",
    ):
        if type(request[name]) is not str or not request[name]:
            raise AuditRequestError(f"{name} must be a non-empty string")
    if type(request["claims"]) is not list or not request["claims"]:
        raise AuditRequestError("claims must be a non-empty list")
    if type(request["limits"]) is not list:
        raise AuditRequestError("limits must be a list")
    for name in (
        "max_output_tokens_per_stage",
        "provider_tpm_limit",
        "token_safety_margin",
    ):
        if type(request[name]) is not int or request[name] < 0:
            raise AuditRequestError(f"{name} must be a non-negative integer")
    if request["max_output_tokens_per_stage"] <= 0:
        raise AuditRequestError("max_output_tokens_per_stage must be positive")
    if request["provider_tpm_limit"] <= 0:
        raise AuditRequestError("provider_tpm_limit must be positive")
    permitted = request.get("permitted_stages", ["A3", "A4"])
    if permitted not in (["A3", "A4"], ["A4"]):
        raise AuditRequestError("permitted_stages must be A3+A4 or A4-only")
    if request.get("a4_justification_contract") == "2" and "resolver" in request:
        if request["resolver"] != "tef_a4_resolution":
            raise AuditRequestError("A4 resolver must be tef_a4_resolution")
        if request.get("resolver_version") != A4_RESOLVER_VERSION:
            raise AuditRequestError(
                f"A4 resolver_version must be {A4_RESOLVER_VERSION}"
            )
    return request


def execution_plan(request_path: Path, request: dict) -> dict:
    stages = tuple(request.get("permitted_stages", ["A3", "A4"]))
    result_directory = PurePosixPath(request["result_directory"])
    if result_directory.is_absolute() or ".." in result_directory.parts:
        raise AuditRequestError("unsafe result_directory")
    result_dir = request_path.parent / result_directory.as_posix()
    corrective = request.get("a4_justification_contract") in {"1", "2"}
    return {
        "stages": stages,
        "run_a3": "A3" in stages,
        "run_a4": "A4" in stages,
        "result_dir": result_dir.as_posix(),
        "a3_output_path": (result_dir / "A3_OUTPUT.json").as_posix(),
        "a4_output_path": (
            result_dir
            / ("A4_CORRECTIVE_OUTPUT.json" if corrective else "A4_OUTPUT.json")
        ).as_posix(),
        "summary_path": (result_dir / "AUDIT_EXECUTION_RESULT.json").as_posix(),
    }


def emit_github_plan(request_path: Path, request: dict) -> str:
    plan = execution_plan(request_path, request)
    return "\n".join(
        (
            f"run_a3={str(plan['run_a3']).lower()}",
            f"run_a4={str(plan['run_a4']).lower()}",
            f"result_dir={plan['result_dir']}",
            f"a3_output_path={plan['a3_output_path']}",
            f"a4_output_path={plan['a4_output_path']}",
            f"summary_path={plan['summary_path']}",
        )
    )


def read_git_baseline_file(baseline: str, evidence_path: str) -> bytes:
    normalized = PurePosixPath(evidence_path)
    if normalized.is_absolute() or ".." in normalized.parts:
        raise AuditRequestError(f"unsafe evidence path: {evidence_path}")
    result = subprocess.run(
        ["git", "show", f"{baseline}:{normalized.as_posix()}"],
        check=False,
        capture_output=True,
    )
    if result.returncode != 0:
        detail = result.stderr.decode("utf-8", errors="replace").strip()
        raise FileNotFoundError(detail or evidence_path)
    return result.stdout


def materialize_evidence(
    request_path: Path,
    request: dict,
    baseline_reader: Callable[[str, str], bytes] = read_git_baseline_file,
) -> tuple[dict, ...]:
    manifest_path = request_path.resolve().parent / request["evidence_manifest"]
    manifest = _read_json(manifest_path, "evidence manifest")
    artifacts = manifest.get("artifacts")
    if type(artifacts) is not list or not artifacts:
        raise AuditRequestError("evidence manifest artifacts must be a non-empty list")
    materialized = []
    for artifact in artifacts:
        if type(artifact) is not dict or type(artifact.get("path")) is not str:
            raise AuditRequestError("invalid evidence manifest artifact")
        source_path = artifact["path"]
        try:
            if artifact.get("audit_artifact") is True:
                data = (request_path.resolve().parent / source_path).read_bytes()
                provenance = "AUDIT_ARTIFACT"
            else:
                data = baseline_reader(request["evaluated_baseline"], source_path)
                provenance = "EVALUATED_BASELINE"
        except (OSError, subprocess.SubprocessError) as exc:
            raise AuditRequestError(
                f"cannot materialize evidence: {source_path}"
            ) from exc
        actual_hash = sha256_bytes(data)
        expected_hash = artifact.get("sha256")
        if expected_hash is not None and actual_hash != expected_hash:
            raise AuditRequestError(
                f"evidence hash mismatch for {source_path}: "
                f"expected {expected_hash}, got {actual_hash}"
            )
        try:
            full_content = data.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise AuditRequestError(
                f"evidence is not authorized textual UTF-8: {source_path}"
            ) from exc
        line_ranges = artifact.get("line_ranges")
        if line_ranges is not None:
            if type(line_ranges) is not list or not line_ranges:
                raise AuditRequestError(f"invalid line_ranges for {source_path}")
            lines = full_content.splitlines()
            selected = []
            for bounds in line_ranges:
                if (
                    type(bounds) is not list
                    or len(bounds) != 2
                    or any(type(value) is not int for value in bounds)
                    or bounds[0] < 1
                    or bounds[1] < bounds[0]
                    or bounds[1] > len(lines)
                ):
                    raise AuditRequestError(f"invalid line range for {source_path}")
                selected.append(
                    f"[LINES {bounds[0]}-{bounds[1]}]\n"
                    + "\n".join(lines[bounds[0] - 1 : bounds[1]])
                )
            content = "\n\n".join(selected) + "\n"
        else:
            content = full_content
        stages = artifact.get("stages", ["A3", "A4"])
        if type(stages) is not list or not stages or not set(stages) <= {"A3", "A4"}:
            raise AuditRequestError(f"invalid stages for {source_path}")
        materialized.append(
            {
                "source_path": source_path,
                "sha256": actual_hash,
                "provenance": provenance,
                "pinned_baseline": request["evaluated_baseline"],
                "line_ranges": line_ranges,
                "stages": stages,
                "content": content,
            }
        )
    return tuple(materialized)


def build_stage_package(
    stage: str,
    request_path: Path,
    request: dict,
    evidence: tuple[dict, ...],
) -> dict:
    if stage not in {"A3", "A4"}:
        raise AuditRequestError(f"unsupported stage: {stage}")
    if stage not in request.get("permitted_stages", ["A3", "A4"]):
        raise AuditRequestError(f"stage {stage} is forbidden by this request")
    input_name = request["a3_input" if stage == "A3" else "a4_input"]
    input_path = request_path.resolve().parent / input_name
    try:
        stage_input = input_path.read_text(encoding="utf-8")
    except OSError as exc:
        raise AuditRequestError(f"missing {stage} input: {input_path}") from exc
    instance_id = request["a3_instance_id" if stage == "A3" else "a4_instance_id"]
    # The package already binds the evaluated baseline and stage.  Omitting those
    # duplicated values from every evidence row is a deterministic, lossless
    # canonicalization; paths, hashes, provenance, ranges and bytes remain intact.
    stage_evidence = tuple(
        {
            key: value
            for key, value in item.items()
            if key not in {"pinned_baseline", "stages"}
        }
        for item in evidence
        if stage in item["stages"]
    )
    evidence_hash = sha256_bytes(canonical_bytes(stage_evidence))
    package = {
        "schema_version": "1",
        "stage": stage,
        "request_id": request["request_id"],
        "unit": request["unit"],
        "evaluated_baseline": request["evaluated_baseline"],
        "instance_id": instance_id,
        "provider": request["provider"],
        "model": request["model"],
        "execution_envelope": {
            "provider_tpm_limit": request["provider_tpm_limit"],
            "max_output_tokens": request["max_output_tokens_per_stage"],
            "safety_margin_tokens": request["token_safety_margin"],
            "token_estimator": "ceil_utf8_bytes_div_4",
        },
        "claims": request["claims"],
        "limits": request["limits"],
        "stage_input": stage_input,
        "evidence": list(stage_evidence),
        "evidence_hash": evidence_hash,
    }
    if stage == "A4":
        if "a4_justification_contract" in request:
            if request["a4_justification_contract"] not in {"1", "2"}:
                raise AuditRequestError("unknown A4 justification contract")
            package["a4_justification_contract"] = request["a4_justification_contract"]
        package["independence"] = {
            "required": request["a4_independence_required"],
            "independent_instance_id": request["a4_independent_instance_id"],
            "producer_runtime": "Codex orchestration",
            "executor_provider": request["provider"],
            "executor_model": request["model"],
            "sufficiency_declared_by_runner": False,
        }
        if request.get("a4_justification_contract") == "2":
            if request.get("resolver") != "tef_a4_resolution":
                raise AuditRequestError("hybrid A4 request must declare resolver")
            if request.get("resolver_version") != A4_RESOLVER_VERSION:
                raise AuditRequestError("hybrid A4 resolver version mismatch")
            package["a4_internal_architecture"] = "HYBRID_DETERMINISTIC_RESOLUTION"
            package["auditor_output_authority"] = {
                "role": "AUDITOR_EVIDENCE_ONLY",
                "global_state_forbidden": True,
                "refutation_valid_forbidden": True,
                "allowed_fields": ["stage", *A4_AUDITOR_EVIDENCE_FIELDS],
                "refutation_validity_version": REFUTATION_VALIDITY_VERSION,
                "resolver_version": A4_RESOLVER_VERSION,
            }
    package["input_hash"] = sha256_bytes(canonical_bytes(package))
    return package


def stage_request_budget(request: dict, package: dict) -> dict:
    prompt = json.dumps(
        package, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    )
    prompt_bytes = len((SYSTEM + prompt).encode("utf-8"))
    estimated_prompt_tokens = (
        prompt_bytes + TOKEN_ESTIMATE_BYTES_PER_TOKEN - 1
    ) // TOKEN_ESTIMATE_BYTES_PER_TOKEN
    output_tokens = request["max_output_tokens_per_stage"]
    safety_margin = request["token_safety_margin"]
    requested_budget = estimated_prompt_tokens + output_tokens + safety_margin
    provider_limit = request["provider_tpm_limit"]
    return {
        "prompt_bytes": prompt_bytes,
        "estimated_prompt_tokens": estimated_prompt_tokens,
        "max_output_tokens": output_tokens,
        "safety_margin_tokens": safety_margin,
        "provider_tpm_limit": provider_limit,
        "requested_budget": requested_budget,
        "fits": requested_budget < provider_limit,
    }


def enforce_stage_request_budget(request: dict, package: dict) -> dict:
    budget = stage_request_budget(request, package)
    if not budget["fits"]:
        raise AuditRequestError(
            f"{package['stage']} package exceeds provider TPM envelope: "
            f"estimated_prompt={budget['estimated_prompt_tokens']}, "
            f"output={budget['max_output_tokens']}, "
            f"safety_margin={budget['safety_margin_tokens']}, "
            f"requested_budget={budget['requested_budget']}, "
            f"provider_limit={budget['provider_tpm_limit']}"
        )
    return budget


def call_groq(
    api_key: str, model: str, package: dict, max_tokens: int
) -> tuple[dict, dict]:
    if model != ALLOWED_MODEL:
        raise AuditRequestError(f"ZERO_COST_ONLY model guard rejected {model!r}")
    prompt = json.dumps(
        package, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    )
    payload = {
        "model": model,
        "messages": [
            {"role": "system", "content": SYSTEM},
            {"role": "user", "content": prompt},
        ],
        "temperature": 0,
        "reasoning_effort": "low",
        "max_completion_tokens": max_tokens,
        "response_format": {"type": "json_object"},
    }
    request = urllib.request.Request(
        API_URL,
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        method="POST",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
            "User-Agent": "tdt-tef-generic-audit-runner/1",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=180) as response:
            data = json.loads(response.read().decode("utf-8"))
            provider_request_id = response.headers.get("x-request-id") or data.get("id")
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"Groq HTTP {exc.code}: {detail}") from exc
    raw_output = json.loads(data["choices"][0]["message"]["content"])
    return raw_output, {
        "provider_request_id": provider_request_id,
        "usage": data.get("usage", {}),
    }


def _output_wrapper(
    stage: str,
    request: dict,
    package: dict,
    raw_output: dict,
    provider_meta: dict,
) -> dict:
    wrapper = {
        "schema_version": "1",
        "stage": stage,
        "request_id": request["request_id"],
        "unit": request["unit"],
        "evaluated_baseline": request["evaluated_baseline"],
        "instance_id": package["instance_id"],
        "provider": request["provider"],
        "model": request["model"],
        "input_hash": package["input_hash"],
        "evidence_hash": package["evidence_hash"],
        "provider_request_id": provider_meta.get("provider_request_id"),
        "timestamp": utc_now(),
        "raw_output": raw_output,
        "raw_output_hash": sha256_bytes(canonical_bytes(raw_output)),
    }
    if stage == "A4" and request.get("a4_justification_contract") == "2":
        required_dimensions = ["cognitive", "procedural", "traceable"]
        if request["a4_independence_required"]:
            required_dimensions.append("additional")
        bundle = resolve_a4_evidence(
            raw_output, required_dimensions=required_dimensions
        )
        wrapper.update(bundle)
        wrapper["resolver_version"] = A4_RESOLVER_VERSION
        resolution = bundle["deterministic_resolution"]
        if resolution["resolution_status"] == RESOLVED:
            wrapper["global_state"] = resolution["global_state"]
    wrapper["output_hash"] = sha256_bytes(canonical_bytes(wrapper))
    return wrapper


def _expected_output_hash(wrapper: dict) -> str:
    value = dict(wrapper)
    value.pop("output_hash", None)
    return sha256_bytes(canonical_bytes(value))


def check_a4_justification(raw: dict) -> list[str]:
    """Check justification structure, never decide whether an audit is correct."""
    allowed = {
        "SATISFACTORIA", "REFUTACION_INSUFICIENTE", "INDEPENDENCIA_INSUFICIENTE",
        "INVALIDA", "AUSENTE", "NO_EVALUABLE",
    }
    state = raw.get("global_state")
    if state not in allowed:
        return ["A4_UNKNOWN_GLOBAL_STATE"]
    if state == "SATISFACTORIA":
        return []
    fields = (
        "non_satisfactory_basis", "failed_requirements", "failed_attack_surfaces",
        "failed_or_missing_oracles", "insufficient_intensity_basis",
        "evidence_references", "normative_source", "remediation_scope",
    )
    def concrete(value: object) -> bool:
        return (isinstance(value, str) and bool(value.strip())
                and value.strip().upper() not in {"NONE", "NOT_APPLICABLE"})

    failures = []
    for field in fields:
        if not isinstance(raw.get(field), str) or not raw[field].strip():
            failures.append(f"A4_JUSTIFICATION_MISSING:{field}")
    required = {
        "non_satisfactory_basis", "failed_requirements", "evidence_references",
        "normative_source", "remediation_scope",
    }
    for field in required:
        if not concrete(raw.get(field)):
            failures.append(f"A4_TRACEABLE_BASIS_MISSING:{field}")
    if state == "REFUTACION_INSUFICIENTE" and not any(
        concrete(raw.get(field)) for field in (
            "failed_attack_surfaces", "failed_or_missing_oracles",
            "insufficient_intensity_basis",
        )
    ):
        failures.append("A4_COVERAGE_OR_INTENSITY_BASIS_MISSING")
    return failures


def check_a4_cross_field_coherence(raw: dict, required_dimensions=None) -> list[str]:
    """Check declarations only; never infer an audit verdict from narrative."""
    failures = []
    statuses = {
        "coverage_status": ("SATISFIED", "INSUFFICIENT", "NOT_EVALUABLE"),
        "intensity_status": ("SATISFIED", "INSUFFICIENT", "NOT_EVALUABLE"),
        "hypothesis_control_status": ("SATISFIED", "MISSING", "INVALID", "NOT_EVALUABLE"),
        "oracle_control_status": ("SATISFIED", "MISSING", "INVALID", "NOT_EVALUABLE"),
        "evidence_integrity_status": ("SATISFIED", "NOT_SATISFIED", "NOT_EVALUABLE"),
        "oracle_independence_status": ("SATISFIED", "NOT_SATISFIED", "NOT_EVALUABLE"),
        "remediation_status": ("DETERMINED", "NOT_DETERMINABLE", "NOT_APPLICABLE"),
    }
    for key, options in statuses.items():
        if raw.get(key) not in options:
            failures.append(f"A4_INVALID_FIELD:{key}")
    if type(raw.get("attempt_present")) is not bool:
        failures.append("A4_INVALID_ATTEMPT")
    valid = raw.get("refutation_valid")
    if type(valid) is not bool and valid != "not_evaluable":
        failures.append("A4_INVALID_VALIDITY")
    dimensions = raw.get("independence_required_dimensions")
    separation = raw.get("independence_dimension_status")
    names = ("cognitive", "procedural", "traceable", "additional")
    if (not isinstance(dimensions, list) or not dimensions
            or any(not isinstance(d, str) or d not in names for d in dimensions)
            or len(set(dimensions)) != len(dimensions)):
        failures.append("A4_INVALID_REQUIRED_DIMENSIONS")
    elif not isinstance(separation, dict) or set(separation) != set(dimensions):
        failures.append("A4_INVALID_DIMENSION_MAP")
    elif any(v not in ("SATISFIED", "NOT_SATISFIED", "NOT_EVALUABLE")
             for v in separation.values()):
        failures.append("A4_INVALID_DIMENSION_STATUS")
    if required_dimensions is not None and dimensions != required_dimensions:
        failures.append("A4_REQUIRED_DIMENSIONS_MISMATCH")
    if failures:
        return failures
    state = raw.get("global_state")
    attempt = raw["attempt_present"]
    if not isinstance(state, str):
        return ["A4_UNKNOWN_STATE"]
    unknown = [key for key in statuses if raw[key] == "NOT_EVALUABLE"]
    bad_controls = [key for key in (
        "hypothesis_control_status", "oracle_control_status",
        "evidence_integrity_status", "oracle_independence_status",
    ) if raw[key] in ("MISSING", "INVALID", "NOT_SATISFIED")]
    deficits = [key for key in ("coverage_status", "intensity_status")
                if raw[key] == "INSUFFICIENT"]
    bad_dims = [d for d in dimensions if separation[d] == "NOT_SATISFIED"]
    unknown_dims = [d for d in dimensions if separation[d] == "NOT_EVALUABLE"]
    permitted_causes = {
        "SATISFACTORIA": [],
        "REFUTACION_INSUFICIENTE": deficits,
        "INDEPENDENCIA_INSUFICIENTE": ["independence:" + d for d in bad_dims],
        "INVALIDA": bad_controls,
        "NO_EVALUABLE": unknown + ["independence:" + d for d in unknown_dims]
                        + (["refutation_valid"] if valid == "not_evaluable" else []),
        "AUSENTE": ["attempt_present"] if not attempt else [],
    }
    coherent = {
        "SATISFACTORIA": attempt and valid is True and not unknown and not bad_controls
                          and not deficits and not bad_dims and not unknown_dims,
        "REFUTACION_INSUFICIENTE": attempt and valid is True and bool(deficits),
        "INDEPENDENCIA_INSUFICIENTE": attempt and bool(bad_dims),
        "INVALIDA": attempt and valid is False and bool(bad_controls),
        "NO_EVALUABLE": attempt and bool(permitted_causes["NO_EVALUABLE"]),
        "AUSENTE": not attempt,
    }
    if not isinstance(state, str) or state not in coherent or not coherent[state]:
        failures.append("A4_STATE_FIELDS_INCOHERENT")
    if valid is True and bad_controls:
        failures.append("A4_VALIDITY_CONTROL_CONTRADICTION")
    if not attempt and (valid is True or raw.get("attacks") or deficits
                        or any(raw[k] != "NOT_EVALUABLE" for k in (
                            "coverage_status", "intensity_status",
