    causes = raw.get("failure_causes")
    if not isinstance(causes, list):
        failures.append("A4_CAUSES_REQUIRED")
        causes = []
    if state == "SATISFACTORIA":
        if causes or raw.get("material_defects"):
            failures.append("A4_SATISFACTORY_ADVERSE_CONTRADICTION")
    elif not causes:
        failures.append("A4_ADVERSE_WITHOUT_BASIS")
    for cause in causes:
        if not isinstance(cause, dict):
            failures.append("A4_INVALID_CAUSE")
            continue
        if cause.get("field") not in permitted_causes.get(state, []):
            failures.append("A4_CAUSE_STATE_MISMATCH")
        for key in ("evidence_reference", "normative_source", "explanation"):
            if not isinstance(cause.get(key), str) or not cause[key].strip():
                failures.append(f"A4_CAUSE_TRACE_MISSING:{key}")
    scope = raw.get("remediation_scope")
    if raw["remediation_status"] == "DETERMINED":
        if (state == "SATISFACTORIA" or not causes or not isinstance(scope, str)
                or not scope.strip()):
            failures.append("A4_REMEDIATION_WITHOUT_SCOPE_OR_CAUSE")
    elif scope is not None:
        failures.append("A4_UNDETERMINED_REMEDIATION_WITH_SCOPE")
    return failures

def check_output_consumability(
    stage: str, request: dict, package: dict, wrapper: dict
) -> dict:
    failures = []
    expected = {
        "request_id": request["request_id"],
        "unit": request["unit"],
        "evaluated_baseline": request["evaluated_baseline"],
        "instance_id": package["instance_id"],
        "input_hash": package["input_hash"],
        "evidence_hash": package["evidence_hash"],
    }
    labels = {
        "request_id": "REQUEST_ID_MISMATCH",
        "unit": "UNIT_MISMATCH",
        "evaluated_baseline": "BASELINE_MISMATCH",
        "instance_id": "INSTANCE_ID_MISMATCH",
        "input_hash": "INPUT_HASH_MISMATCH",
        "evidence_hash": "EVIDENCE_HASH_MISMATCH",
    }
    for field, expected_value in expected.items():
        if wrapper.get(field) != expected_value:
            failures.append(labels[field])
    raw = wrapper.get("raw_output")
    hybrid_a4 = stage == "A4" and request.get("a4_justification_contract") == "2"
    if type(raw) is not dict or raw.get("stage") != stage:
        failures.append("INVALID_STAGE_SCHEMA")
    elif hybrid_a4:
        if "global_state" in raw:
            failures.append("A4_LLM_GLOBAL_STATE_FORBIDDEN")
    elif "global_state" not in raw:
        failures.append("INVALID_STAGE_SCHEMA")
    if not wrapper.get("output_hash"):
        failures.append("OUTPUT_HASH_MISSING")
    elif wrapper["output_hash"] != _expected_output_hash(wrapper):
        failures.append("OUTPUT_HASH_MISMATCH")
    if type(raw) is dict and wrapper.get("raw_output_hash") != sha256_bytes(
        canonical_bytes(raw)
    ):
        failures.append("RAW_OUTPUT_NOT_PRESERVED")
    if stage == "A4" and type(raw) is dict:
        if request.get("a4_justification_contract") == "1":
            failures.extend(check_a4_justification(raw))
        if hybrid_a4:
            if wrapper.get("resolver_version") != A4_RESOLVER_VERSION:
                failures.append("A4_UNKNOWN_RESOLVER_VERSION")
            else:
                required_dimensions = ["cognitive", "procedural", "traceable"]
                if request["a4_independence_required"]:
                    required_dimensions.append("additional")
                failures.extend(
                    validate_resolution_bundle(
                        raw, wrapper, required_dimensions=required_dimensions
                    )
                )
            resolution = wrapper.get("deterministic_resolution")
            if type(resolution) is not dict:
                failures.append("A4_RESOLUTION_MISSING")
            elif resolution.get("resolution_status") != RESOLVED:
                failures.append(
                    "A4_" + str(resolution.get("resolution_status", "RESOLUTION_MISSING"))
                )
                if "global_state" in wrapper:
                    failures.append("A4_GLOBAL_STATE_PUBLISHED_ON_UNRESOLVED")
            elif wrapper.get("global_state") != resolution.get("global_state"):
                failures.append("A4_PUBLISHED_STATE_MISMATCH")
        if raw.get("adverse_result_preserved") is not True:
            failures.append("NEGATIVE_FINDINGS_PRESERVATION_NOT_ATTESTED")
    return {"consumable": not failures, "failures": failures}


def _write_json(path: Path, value: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(
        json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    temporary.replace(path)


def _contradiction(a3: dict, a4: dict, gates_pass: bool) -> str:
    if not gates_pass:
        return "NOT_DETERMINABLE"
    a3_state = a3.get("global_state")
    a4_state = a4.get("global_state")
    a3_adverse = a3_state in {"DEFECTUOSA", "CONTRADICHA"} or bool(
        a3.get("material_adverse_findings")
    )
    a4_positive = a4_state == "SATISFACTORIA"
    a4_adverse = a4_state in {"INVALIDA", "REFUTACION_INSUFICIENTE"} or bool(
        a4.get("material_defects")
    )
    a3_positive = a3_state == "SATISFACTORIA"
    return "SI" if (a3_adverse and a4_positive) or (a4_adverse and a3_positive) else "NO"


def execute_audit(
    request_path: Path,
    *,
    api_key: str,
    provider_call: Callable = call_groq,
    evidence_reader: Callable[[str, str], bytes] = read_git_baseline_file,
