def execute_stage(
    request_path: Path,
    stage: str,
    *,
    api_key: str,
    provider_call: Callable = call_groq,
    evidence_reader: Callable[[str, str], bytes] = read_git_baseline_file,
) -> dict:
    request, package, result_dir = _stage_context(
        request_path, stage, evidence_reader
    )
    output_path = _stage_output_path(result_dir, request, stage)
    if output_path.exists():
        try:
