        raise AuditRequestError("inter-stage wait is only defined after A3")
    if execution_result.get("stage") != completed_stage:
        raise AuditRequestError("execution result stage mismatch")
    if execution_result.get("request_id") != request["request_id"]:
        raise AuditRequestError("execution result request mismatch")
    executed = execution_result.get("executed")
    if type(executed) is not bool:
        raise AuditRequestError("execution result must declare executed as boolean")
    seconds = float(request["min_seconds_between_stages"])
    if executed:
        sleeper(seconds)
    return {
        "stage": completed_stage,
        "wait_applied": executed,
        "wait_seconds": seconds if executed else 0.0,
    }


def write_execution_summary(
    request_path: Path,
