        "INDEPENDENCIA_INSUFICIENTE": bad_dimensions,
        "NO_EVALUABLE": unknowns | unknown_controls,
        "SATISFACTORIA": set(),
    }
    if not attempt:
        candidates.add("AUSENTE")
    if attempt and validity_status == "INVALID":
        candidates.add("INVALIDA")
    if attempt and validity_status == "VALID" and deficits:
        candidates.add("REFUTACION_INSUFICIENTE")
    if attempt and validity_status == "VALID" and bad_dimensions:
        candidates.add("INDEPENDENCIA_INSUFICIENTE")
    if attempt and validity_status == "NOT_EVALUABLE":
        candidates.add("NO_EVALUABLE")
    if attempt and validity_status == "VALID" and unknowns:
        candidates.add("NO_EVALUABLE")
    all_satisfied = (
        attempt
        and validity_status == "VALID"
        and evidence["coverage_status"] == "SATISFIED"
        and evidence["intensity_status"] == "SATISFIED"
        and not bad_dimensions
        and not unknowns
        and all(dimension_status[name] == "SATISFIED" for name in dimensions)
    )
    if all_satisfied:
        candidates.add("SATISFACTORIA")
    return candidates, causes


def _cause_errors(evidence: dict, state: str, permitted: set[str]) -> list[str]:
    causes = evidence["failure_causes"]
    if state == "SATISFACTORIA":
        return ["A4_SATISFACTORY_WITH_FAILURE_CAUSE"] if causes else []
    if not causes:
        return ["A4_ADVERSE_WITHOUT_TRACEABLE_CAUSE"]
    errors = []
    for cause in causes:
        if type(cause) is not dict:
            errors.append("A4_INVALID_CAUSE")
            continue
        if cause.get("field") not in permitted:
            errors.append("A4_CAUSE_STATE_MISMATCH")
        for field in ("evidence_reference", "normative_source", "explanation"):
            if type(cause.get(field)) is not str or not cause[field].strip():
                errors.append(f"A4_CAUSE_TRACE_MISSING:{field}")
    return errors


def _cross_field_errors(evidence: dict, state: str, permitted: set[str]) -> list[str]:
    errors = _cause_errors(evidence, state, permitted)
    attempt = evidence["attempt_present"]
    if not attempt and (
        evidence["attacks"]
        or evidence["material_defects"]
        or evidence["negative_findings"]
        or any(
            evidence[field] != "NOT_EVALUABLE"
            for field in (
                "coverage_status",
                "intensity_status",
                "hypothesis_control_status",
                "oracle_control_status",
                "oracle_independence_status",
                "evidence_integrity_status",
            )
        )
    ):
        errors.append("A4_ABSENCE_RESULTS_CONTRADICTION")
    remediation = evidence["remediation_status"]
    scope = evidence["remediation_scope"]
    if remediation == "DETERMINED":
        if state == "SATISFACTORIA" or not isinstance(scope, str) or not scope.strip():
            errors.append("A4_REMEDIATION_WITHOUT_SCOPE_OR_CAUSE")
    elif scope is not None:
        errors.append("A4_UNDETERMINED_REMEDIATION_WITH_SCOPE")
    return errors


def resolve_a4_evidence(
    raw_output: dict,
    *,
    resolver_version: str = A4_RESOLVER_VERSION,
    required_dimensions: list[str] | None = None,
) -> dict:
    """Normalize auditor evidence and derive a state only when uniquely authorized."""
    evidence, normalization_errors = normalize_auditor_evidence(raw_output)
    normalized_hash = _sha256(evidence)
    validity = {
        "refutation_validity_version": REFUTATION_VALIDITY_VERSION,
        "refutation_validity_status": UNRESOLVED_CONTRADICTION,
        "reasons": list(normalization_errors),
    }
    resolution = {
        "resolver_version": resolver_version,
        "resolution_status": UNRESOLVED_CONTRADICTION,
        "reasons": list(normalization_errors),
    }
    if resolver_version != A4_RESOLVER_VERSION:
        resolution["reasons"] = ["A4_UNKNOWN_RESOLVER_VERSION"]
    elif not normalization_errors:
        errors = _base_errors(evidence)
        if (
            not errors
            and required_dimensions is not None
            and evidence["independence_required_dimensions"] != required_dimensions
        ):
            errors.append("A4_REQUIRED_DIMENSIONS_MISMATCH")
        if errors:
            validity["reasons"] = errors
            resolution["reasons"] = errors
        else:
            validity = derive_refutation_validity(evidence)
            validity_status = validity.get("refutation_validity_status")
            if validity_status in {
                UNRESOLVED_CONTRADICTION,
                UNRESOLVED_NORMATIVE_AMBIGUITY,
            }:
                resolution = {
                    "resolver_version": resolver_version,
                    "resolution_status": validity_status,
                    "reasons": list(validity["reasons"]),
                }
            else:
                candidates, permitted_causes = _candidate_states(evidence, validity)
                if len(candidates) > 1:
                    resolution = {
                        "resolver_version": resolver_version,
                        "resolution_status": UNRESOLVED_NORMATIVE_AMBIGUITY,
                        "candidate_states": sorted(candidates),
                        "reasons": ["A4_NO_PUBLISHED_PRECEDENCE"],
                    }
                elif len(candidates) == 1:
                    state = next(iter(candidates))
                    errors = _cross_field_errors(
                        evidence, state, permitted_causes[state]
                    )
                    if errors:
                        resolution["reasons"] = errors
                    else:
                        resolution = {
                            "resolver_version": resolver_version,
                            "resolution_status": RESOLVED,
                            "global_state": state,
                            "reasons": [],
                        }
                else:
                    resolution["reasons"] = ["A4_NO_UNEQUIVOCAL_STATE"]
    validity_material = {
        "normalized_evidence_hash": normalized_hash,
        "derived_refutation_validity": validity,
    }
    validity_hash = _sha256(validity_material)
    resolution_material = {
        "normalized_evidence_hash": normalized_hash,
        "refutation_validity_hash": validity_hash,
        "resolution": resolution,
    }
    return {
        "auditor_evidence_normalized": evidence,
        "normalized_evidence_hash": normalized_hash,
        "refutation_validity_version": REFUTATION_VALIDITY_VERSION,
        "derived_refutation_validity": validity,
        "refutation_validity_hash": validity_hash,
        "deterministic_resolution": resolution,
        "resolution_hash": _sha256(resolution_material),
    }


def validate_resolution_bundle(
    raw_output: dict,
    bundle: dict,
    *,
    resolver_version: str = A4_RESOLVER_VERSION,
    required_dimensions: list[str] | None = None,
) -> list[str]:
    """Reject changed evidence, resolution, hashes, or resolver versions."""
    if resolver_version != A4_RESOLVER_VERSION:
        return ["A4_UNKNOWN_RESOLVER_VERSION"]
    expected = resolve_a4_evidence(
        raw_output,
        resolver_version=resolver_version,
        required_dimensions=required_dimensions,
    )
    failures = []
    for field, label in (
        ("auditor_evidence_normalized", "A4_NORMALIZED_EVIDENCE_MISMATCH"),
        ("normalized_evidence_hash", "A4_NORMALIZED_EVIDENCE_HASH_MISMATCH"),
        ("refutation_validity_version", "A4_REFUTATION_VALIDITY_VERSION_MISMATCH"),
        ("derived_refutation_validity", "A4_REFUTATION_VALIDITY_MISMATCH"),
        ("refutation_validity_hash", "A4_REFUTATION_VALIDITY_HASH_MISMATCH"),
        ("deterministic_resolution", "A4_RESOLUTION_MISMATCH"),
        ("resolution_hash", "A4_RESOLUTION_HASH_MISMATCH"),
    ):
        if bundle.get(field) != expected[field]:
            failures.append(label)
    return failures
